"""Writes softmax_tables.h (the 1024-entry 2^(-i/1024) table of the softmax kernel) from smx_emu.tables(),
so the HLS core and the torch emulation use the same integers.   python gen_tables.py"""

from pathlib import Path

from smx_emu import tables

t23, s13 = tables()
vals = [(t << 13) | s for t, s in zip(t23, s13)]
lines = []
for i in range(0, 1024, 8):
    lines.append(",".join(f"0x{v:09x}ULL" for v in vals[i : i + 8]))
hdr = (
    "// Generated by gen_tables.py from smx_emu.tables(). Do not edit.\n"
    "// Entry i = T23[i] << 13 | S13[i]: T23 = round(2^23 * 2^(-i/1024) * 32767/32768), S13 = round(T23 * ln2 / 1024).\n"
    "#pragma once\n"
    "#define SMX_TAB_INIT { \\\n" + ", \\\n".join(lines) + " }\n"
)
out = Path(__file__).with_name("softmax_tables.h")
out.write_text(hdr)
print(f"wrote {out} ({len(vals)} entries, T23[0]={t23[0]} T23[1023]={t23[1023]} S13 max={max(s13)})")
